import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxSelect,
  JxStepper,
} from '@jinx-ui/react';

export interface RegistrationValues {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationWizardProps {
  onSubmit: (values: RegistrationValues) => void;
}

const emptyValues: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'by', label: 'Беларусь' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'am', label: 'Армения' },
];

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(emptyValues);

  const setField = (field: keyof RegistrationValues, value: string) => {
    setValues((current) => ({ ...current, [field]: value }));
  };

  const isLast = step === steps.length - 1;
  const countryLabel =
    countries.find((country) => country.value === values.country)?.label ?? '—';

  const summary: Array<{ label: string; value: string }> = [
    { label: 'Имя', value: values.name || '—' },
    { label: 'Почта', value: values.email || '—' },
    { label: 'Телефон', value: values.phone || '—' },
    { label: 'Страна', value: countryLabel },
    { label: 'Город', value: values.city || '—' },
    { label: 'Улица и дом', value: values.street || '—' },
    { label: 'Индекс', value: values.zip || '—' },
  ];

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'grid', gap: '24px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={(event) => setField('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={(event) => setField('email', event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            placeholder="900 000-00-00"
            value={values.phone}
            onChange={(event) => setField('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={values.country}
            onValueChange={(value) => setField('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={(event) => setField('city', event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={(event) => setField('street', event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            inputMode="numeric"
            value={values.zip}
            onChange={(event) => setField('zip', event.target.value)}
            helperText="Шесть цифр"
          />
        </div>
      )}

      {step === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'minmax(120px, auto) 1fr',
            gap: '8px 16px',
            margin: 0,
            padding: '16px',
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
            color: 'var(--jx-text)',
          }}
        >
          {summary.map((row) => (
            <div key={row.label} style={{ display: 'contents' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>{row.label}</dt>
              <dd style={{ margin: 0 }}>{row.value}</dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

export default RegistrationWizard;

